// Batch C2c (OI-474): E230 Standing Single Leg Curl becomes a bodyweight row.
//
// The edit is a RECORD (scripts/data/library_e230_retag.json: before / after for nine keys, generated by node from the
// HEAD library) applied by a stage of scripts/add_library_batch_c_v15.js, never a hand edit. This test pins the shipped
// row to the record, the record to the convention of the 92 other bodyweight strength rows, the new text to the
// equipment audit's idea of "no cable, no load", and the record's `before` to the frozen hash of the old row, so a
// record whose `before` is not what shipped before cannot stand.
//
// Run: flutter test test/contracts/library_e230_retag_test.dart
import 'dart:collection';
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';

import '../../scripts/migration_ledger_hash_lib.dart' show sha256Hex;

typedef Json = Map<String, dynamic>;

const _recordPath = 'scripts/data/library_e230_retag.json';
const _libraryPath = 'assets/data/exercise_library.json';
const _fixturePath = 'test/fixtures/exercise_library_v12_row_hashes.json';
const _coreFieldsPath = 'scripts/data/library_core_fields_v13.json';
const _mediaKeys = ['media_slug', 'media_version', 'media_source'];
const _nineKeys = [
  'equipment_needed',
  'equipment_tier',
  'gym_availability',
  'logging_type',
  'standard_swap',
  'coaching_cues',
  'common_mistakes',
  'warmup_protocol',
  'pro_tip',
];
const _textKeys = ['coaching_cues', 'common_mistakes', 'warmup_protocol', 'pro_tip'];

Json _json(String path) => jsonDecode(File(path).readAsStringSync()) as Json;

bool _same(Object? a, Object? b) => jsonEncode(a) == jsonEncode(b);

String _rowHash(Json row, List<String> keys) => sha256Hex(
    utf8.encode(jsonEncode(SplayTreeMap<String, dynamic>.from({for (final k in keys) k: row[k]}))));

Iterable<String> _strings(Object? v) => v is List ? v.map((e) => '$e') : ['$v'];

void main() {
  final record = _json(_recordPath);
  final before = (record['before'] as Map).cast<String, dynamic>();
  final after = (record['after'] as Map).cast<String, dynamic>();
  final lib = (jsonDecode(File(_libraryPath).readAsStringSync()) as List).cast<Json>();
  final e230 = lib.singleWhere((r) => r['id'] == 'E230');

  group('the record', () {
    test('names E230, picture 0795 and the same nine keys in before and after, every one changed', () {
      expect(record['id'], 'E230');
      expect(record['gif'], '0795');
      expect(before.keys.toList(), _nineKeys);
      expect(after.keys.toList(), _nineKeys);
      for (final k in _nineKeys) {
        expect(_same(before[k], after[k]), isFalse, reason: '$k is in the record but does not change');
      }
      expect(RegExp(r'^[0-9a-f]{64}$').hasMatch(record['frozen_sha256_before'] as String), isTrue);
    });

    test('the record gif is the picture the media table and the old-rows input give E230', () {
      final table = _json('scripts/data/library_media_v16.json');
      final slug = (table['rows'] as Map)['E230'] as String;
      expect(slug.startsWith('${record['gif']}-'), isTrue, reason: 'table slug $slug vs record gif ${record['gif']}');
      final input = _json('docs/audit/library-old-rows-media-input.json');
      final entry = (input['entries'] as List).cast<Map<String, dynamic>>().singleWhere((e) => e['id'] == 'E230');
      expect(entry['gif'], record['gif']);
    });

    test('the shipped E230 equals the record after on all nine keys', () {
      for (final k in _nineKeys) {
        expect(_same(e230[k], after[k]), isTrue, reason: 'E230.$k: shipped ${jsonEncode(e230[k])} vs record ${jsonEncode(after[k])}');
      }
    });

    test('MIRROR: the record before rebuilds the old row (frozen hash over the fixture keys; core fields for the rest)', () {
      final overlaid = {...e230, ...before};
      for (final k in _mediaKeys) {
        overlaid.remove(k);
      }
      final entry = (_json(_fixturePath)['E230'] as Map).cast<String, dynamic>();
      final keys = (entry['keys'] as List).cast<String>();
      expect(keys.length, 35, reason: 'the fixture records 35 keys for E230');
      expect(_rowHash(overlaid, keys), record['frozen_sha256_before'],
          reason: 'before + the untouched keys must hash to the old frozen row');
      // The fixture does not hold gym_availability, core_levels, discipline, requires_coaching, high_impact,
      // variant_family: the dead v13 script's own record is the only other witness of the old values.
      final core = ((_json(_coreFieldsPath)['rows'] as Map)['E230'] as Map).cast<String, dynamic>();
      expect(core.keys.toSet(), {'core_levels', 'discipline', 'gym_availability', 'requires_coaching', 'high_impact', 'variant_family'});
      for (final e in core.entries) {
        expect(_same(overlaid[e.key], e.value), isTrue, reason: 'E230.${e.key}: overlaid ${jsonEncode(overlaid[e.key])} vs v13 ${jsonEncode(e.value)}');
      }
    });
  });

  group('the shipped row follows the convention of the other bodyweight strength rows', () {
    final sample = lib
        .where((r) =>
            r['id'] != 'E230' &&
            r['discipline'] == 'strength' &&
            r['is_active'] == true &&
            _same(r['equipment_needed'], ['bodyweight']))
        .toList();

    test('the sample is large (a filter that matches nothing proves nothing; 92 rows on 2026-11-06)', () {
      expect(sample.length, greaterThanOrEqualTo(50));
    });

    // The convention is the MODAL value of the sample (all 92 rows share one tier set and one gym_availability today), so a later
    // bodyweight row that differs does not turn this contract red for a reason that has nothing to do with E230.
    String modal(Iterable<String> values) {
      final counts = <String, int>{};
      for (final v in values) {
        counts[v] = (counts[v] ?? 0) + 1;
      }
      return (counts.entries.toList()..sort((a, b) => b.value.compareTo(a.value))).first.key;
    }

    test('equipment_needed is exactly bodyweight; the tier set and gym_availability are the most common ones in the sample', () {
      expect(e230['equipment_needed'], ['bodyweight']);
      expect(jsonEncode(e230['equipment_tier']), modal([for (final r in sample) jsonEncode(r['equipment_tier'])]));
      expect(e230['gym_availability'], modal([for (final r in sample) '${r['gym_availability']}']));
    });

    test('logging_type is one the sample uses (membership, not equality: 81 bodyweight_reps, 9 timed, 2 weight_reps)', () {
      final logging = {for (final r in sample) r['logging_type']};
      expect(logging, contains(e230['logging_type']));
      expect(e230['logging_type'], 'bodyweight_reps');
    });

    test('standard_swap is empty, the value of most of the sample (the old value names no row)', () {
      final empty = sample.where((r) => r['standard_swap'] == '').length;
      expect(empty * 2, greaterThan(sample.length));
      expect(e230['standard_swap'], '');
    });
  });

  group('the new text', () {
    final text = [for (final k in _textKeys) ..._strings(e230[k])];

    test('no cue, mistake, warmup or tip names a cable, a machine or a load', () {
      final bad = RegExp(r'\b(cables?|weights?|weighted|dumbbells?|barbells?|kettlebells?|machines?|stack|straps?|plates?|loads?|loaded)\b', caseSensitive: false);
      final hits = [for (final s in text) if (bad.hasMatch(s)) s];
      expect(hits, isEmpty, reason: 'text that still names equipment or a load: $hits');
    });

    test('no semicolon (the cue text is stored in an array literal and joined elsewhere) and ASCII only', () {
      expect(text.where((s) => s.contains(';')), isEmpty);
      expect(text.where((s) => RegExp(r'[^\x20-\x7e]').hasMatch(s)), isEmpty);
      expect(text, isNotEmpty);
    });

    test('the first cue (the plan note) and the rest are non-empty strings', () {
      expect((e230['coaching_cues'] as List).length, greaterThanOrEqualTo(3));
      expect((e230['common_mistakes'] as List).length, greaterThanOrEqualTo(3));
      expect(text.where((s) => s.trim().isEmpty), isEmpty);
    });
  });
}
